// API controller
[HttpGet("{id}")]
public async Task<IActionResult> Get(Guid id)
{
    using var activity = _activitySource.StartActivity("GetExpense");
    activity?.SetTag("expense.id", id);
    var expense = await _dbContext.Expenses.FindAsync(id);
    return Ok(expense);
}

// Background worker
public async Task ProcessReimbursementBatch(CancellationToken ct)
{
    using var activity = _activitySource.StartActivity("ReimbursementBatch");
    foreach (var batch in batches)
    {
        using var span = _activitySource.StartActivity("ProcessBatch");
        span.SetTag("batch.size", batch.Count);
        await ProcessAsync(batch, ct);
    }
}
